fn read_project_json<T: serde::de::DeserializeOwned>(path: &str) -> Result<T> {
    use std::io::Read;
    let mut bytes = Vec::new();
    std::fs::File::open(path)?
        .take(48 * 1024 + 1)
        .read_to_end(&mut bytes)?;
    if bytes.len() > 48 * 1024 {
        return Err(invalid("project plan/bindings file exceeds 48 KiB"));
    }
    serde_json::from_slice(&bytes).map_err(|_| invalid("invalid project plan/bindings JSON"))
}

fn sync_cli(a: &mut Args, c: &Client) -> Result<u8> {
    use crate::sync::{Command as S, Config, Schedule};
    let verb = a.required(1)?;
    if matches!(verb.as_str(), "apply" | "applied" | "cancel-apply") {
        let id = a
            .required(2)?
            .parse::<OperationId>()
            .map_err(|_| invalid("invalid capture/apply ID"))?;
        let command = if verb == "applied" {
            crate::incremental::Command::Status { id }
        } else {
            let key = a
                .take("--key")
                .unwrap_or_else(|| OperationId::new().to_string());
            if verb == "apply" {
                crate::incremental::Command::Apply {
                    capture_id: id,
                    key,
                }
            } else {
                crate::incremental::Command::Cancel { id, key }
            }
        };
        a.finish(3)?;
        println!("{}", c.call(Action::ManagedIncremental { command })?);
        return Ok(0);
    }
    if verb == "capture" {
        return capture_cli(a, c);
    }
    let read = matches!(
        verb.as_str(),
        "list" | "show" | "runs" | "status" | "inspect" | "review-resync"
    );
    let key = if read {
        String::new()
    } else {
        a.take("--key")
            .unwrap_or_else(|| OperationId::new().to_string())
    };
    let id = if matches!(verb.as_str(), "create" | "list" | "inspect") {
        None
    } else {
        Some(
            a.required(2)?
                .parse::<OperationId>()
                .map_err(|_| invalid("invalid snapshot policy/run ID"))?,
        )
    };
    let command = match verb.as_str() {
        "inspect" => S::Inspect {
            branch: a
                .take("--branch")
                .ok_or_else(|| invalid("inspect requires --branch"))?,
        },
        "review-resync" => S::ReviewResync { id: id.unwrap() },
        "resync" => S::Resync {
            id: id.unwrap(),
            expected_revision: sync_revision(a)?,
            review_hash: a
                .take("--review-hash")
                .ok_or_else(|| invalid("resync requires --review-hash"))?,
            key,
        },
        "list" => S::List,
        "show" => S::Get { id: id.unwrap() },
        "status" => S::Run { id: id.unwrap() },
        "runs" => S::Runs {
            id: id.unwrap(),
            limit: a.number("--limit", 50)? as usize,
        },
        "cancel" => S::Cancel {
            id: id.unwrap(),
            key,
        },
        "create" | "update" => {
            let schedule = a
                .take("--every-seconds")
                .map(|s| {
                    s.parse::<u64>()
                        .map_err(|_| invalid("invalid --every-seconds"))
                })
                .transpose()?
                .map(|interval_seconds| Schedule {
                    interval_seconds,
                    timezone: "UTC".into(),
                    missed_run: "coalesce".into(),
                });
            let mode = a.take("--mode").unwrap_or_else(|| "snapshot".into());
            let strategy = a.take("--strategy").unwrap_or_else(|| {
                if matches!(mode.as_str(), "triggered" | "continuous") {
                    "incremental".into()
                } else {
                    "full".into()
                }
            });
            let continuous = if mode == "continuous" {
                Some(crate::sync::Continuous {
                    freshness_ms: a.number("--freshness-ms", 5000)?,
                    batch_interval_ms: a.number("--batch-interval-ms", 500)?,
                })
            } else {
                None
            };
            let config = Config {
                continuous,
                mode,
                strategy,
                schedule,
                limits: crate::store::ExportLimits {
                    max_bytes: a.number("--max-bytes", 1024 * 1024 * 1024)?,
                    timeout_ms: a.number("--timeout-ms", 300000)?,
                },
            };
            config.validate()?;
            if verb == "create" {
                S::Create {
                    branch: a
                        .take("--branch")
                        .ok_or_else(|| invalid("snapshot policy requires --branch"))?,
                    key,
                    config,
                }
            } else {
                S::Update {
                    id: id.unwrap(),
                    expected_revision: sync_revision(a)?,
                    key,
                    config,
                }
            }
        }
        "run" | "pause" | "resume" | "delete" => {
            let id = id.unwrap();
            let expected_revision = sync_revision(a)?;
            match verb.as_str() {
                "run" => S::RunNow {
                    id,
                    expected_revision,
                    key,
                },
                "pause" => S::Pause {
                    id,
                    expected_revision,
                    key,
                },
                "resume" => S::Resume {
                    id,
                    expected_revision,
                    key,
                },
                _ => S::Delete {
                    id,
                    expected_revision,
                    key,
                },
            }
        }
        _ => return Err(invalid("unknown sync command; use --help")),
    };
    a.finish(if matches!(verb.as_str(), "create" | "list" | "inspect") {
        2
    } else {
        3
    })?;
    println!("{}", c.call(Action::ManagedSnapshots { command })?);
    Ok(0)
}
fn capture_cli(a: &mut Args, c: &Client) -> Result<u8> {
    use crate::capture::{Command as C, Limits};
    let verb = a.required(2)?;
    let id = a
        .required(3)?
        .parse::<OperationId>()
        .map_err(|_| invalid("invalid policy/capture ID"))?;
    let key = if verb == "status" {
        String::new()
    } else {
        a.take("--key")
            .unwrap_or_else(|| OperationId::new().to_string())
    };
    let command = match verb.as_str() {
        "start" => C::Start {
            policy_id: id,
            expected_revision: sync_revision(a)?,
            key,
            limits: Limits {
                spool_bytes: a.number("--spool-bytes", 512 * 1024 * 1024)?,
                wal_bytes: a.number("--wal-bytes", 512 * 1024 * 1024)?,
            },
        },
        "status" => C::Status { id },
        "pause" => C::Pause { id, key },
        "resume" => C::Resume { id, key },
        "delete" => C::Delete { id, key },
        _ => return Err(invalid("unknown capture command")),
    };
    a.finish(4)?;
    println!("{}", c.call(Action::ManagedCapture { command })?);
    Ok(0)
}
fn sync_revision(a: &mut Args) -> Result<i64> {
    let n = a
        .take("--revision")
        .ok_or_else(|| invalid("snapshot policy requires --revision"))?
        .parse::<i64>()
        .map_err(|_| invalid("invalid snapshot policy revision"))?;
    if n < 1 {
        return Err(invalid("snapshot policy revision must be positive"));
    }
    Ok(n)
}

fn analytical_resource_profile(
    value: Option<String>,
) -> Result<crate::store::AnalyticalResourceProfile> {
    use crate::store::AnalyticalResourceProfile;
    match value.as_deref().unwrap_or("compact") {
        "compact" => Ok(AnalyticalResourceProfile::Compact),
        "analytical" => Ok(AnalyticalResourceProfile::Analytical),
        _ => Err(invalid("resource profile requires compact or analytical")),
    }
}

