/// Fail before opening SQLite, incrementing ownership or launching recovery.
/// Release changes require the explicit, backed-up upgrade transaction.
pub(crate) fn check_data_root(root: &Path) -> Result<()> {
    if root.join("restore-incomplete").exists() {
        return Err(crate::store::error::conflict(
            "incomplete restore; restore the verified backup into another new directory",
        ));
    }
    if root.join("upgrade.json").exists() {
        return Err(crate::store::error::conflict(
            "interrupted upgrade; rerun the staged installer with the same upgrade and backup options",
        ));
    }
    let path = root.join("runtime.json");
    if path.exists() {
        let runtime: serde_json::Value = serde_json::from_slice(&fs::read(path)?)?;
        if !matches!(runtime["version"].as_u64(), Some(1 | 2)) {
            return Err(invalid("unsupported native runtime format"));
        }
        if let Some(expected) = runtime["installation_identity"].as_str() {
            let installed = Installation::discover()?
                .ok_or_else(|| invalid("this data root requires its installed release"))?;
            if installed.identity != expected {
                return Err(crate::store::error::conflict(
                    "release mismatch; use the explicit backup and upgrade workflow before opening this data root",
                ));
            }
        }
    }
    Ok(())
}

/// Fork portable source into a new private, unbound definition; never mutate input.
pub fn fork(
    directory: &Path,
    destination: &Path,
    name: &str,
    target: Option<&str>,
) -> Result<Value> {
    let id = supabricks_core::resource::ProjectId::new();
    super::manifest::identity(id, name)?;
    let temporary = tempfile::tempdir()?;
    let archive = temporary.path().join("source.sbproj");
    pack(directory, &archive, target)?;
    let (report, mut files) = read(&archive, target)?;
    let mut manifest: toml::Value =
        super::manifest::parse(&files["supabricks.toml"], "supabricks.toml")?;
    manifest["id"] = toml::Value::String(id.to_string());
    manifest["name"] = toml::Value::String(name.into());
    files.insert(
        "supabricks.toml".into(),
        toml::to_string_pretty(&manifest)?.into_bytes(),
    );
    let mut memory = Source::memory(files.clone())?;
    let inspection = inspect_inputs(&mut memory, Some(&report.inspection.target))?;
    let publication = super::publication::Publication::new(destination)?;
    for (path, bytes) in files {
        publication.write(&path, &bytes)?;
    }
    publication.write(MARKER,&canonical(&json!({"format_version":1,"state":"unbound","origin_definition_id":report.inspection.definition.id,"origin_content_sha256":report.content_sha256,"definition_id":id}))?)?;
    publication.publish_directory()?;
    Ok(
        json!({"api_version":1,"definition_id":id,"origin_definition_id":report.inspection.definition.id,"unbound":true,"inspection":inspection}),
    )
}

/// Fixed-worktree drafts never follow a symlink in any destination component.
pub(crate) fn write_draft(root: &Path, path: &str, bytes: &[u8]) -> Result<()> {
    let parts = super::source::path(path, false)?;
    let mut parent = Directory::project(root)?;
    for part in &parts[..parts.len() - 1] {
        parent = parent.child(OsStr::new(part), true)?;
    }
    let temporary = format!(
        ".supabricks-draft-{}",
        supabricks_core::resource::OperationId::new()
    );
    let name = OsStr::new(&temporary);
    let mut file = parent.open(name, libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL)?;
    let result = (|| {
        file.write_all(bytes)?;
        file.sync_all()?;
        parent.move_to(name, &parent, OsStr::new(parts.last().unwrap()))
    })();
    if result.is_err() {
        let _ = parent.unlink(name);
    }
    result
}

